Page('project://pages/home/home.js', {
  data: {
    dateText: '10月18日 · 今天',
    hero: {},
    era: {},
    modern: {},
    tih: [],
    tihTotal: 0,
    tihMore: false,
    tihDate: '',
    sheet: { open: false, title: '', list: [] },
    info: { open: false, title: '', paragraphs: [] },
    fontClass: 'm'
  },

  onShow() {
    this.setTab();
    font.apply(this);
    this.apply();
    // 60s「历史上的今天」：失败自动隐藏板块，不占位
    this.loadTih();
    hd.refresh((changed) => {
      if (changed) this.apply();
    });
  },

  setTab() {
    if (typeof this.getTabBar === 'function' && this.getTabBar()) {
      this.getTabBar().setData({ active: 'home' });
    }
  },

  apply() {
    const history = hd.get();
    const now = new Date();
    const month = now.getMonth() + 1;
    const day = now.getDate();

    // 今日史事：按「月-日」匹配日期库；无匹配时回退编辑精选
    const daily = history.daily.find((item) => item.month === month && item.day === day) || history.dailyFallback;
    const dailyEvent = history.events.find((item) => item.id === daily.eventId);
    const hero = dailyEvent
      ? { eventId: dailyEvent.id, title: '今日史事', desc: `${dailyEvent.yearText}，${dailyEvent.desc}` }
      : { eventId: daily.eventId, title: '今日史事', desc: daily.desc || '' };
    const era = history.topics.find((item) => item.id === 'tang');
    const modern = history.topics.find((item) => item.id === 'modern-china');

    this.setData({
      dateText: `${month}月${day}日 · 今天`,
      hero,
      era,
      modern
    });
  },

  // 「历史上的今天」板块：真数据来自 60s API（天级缓存 6h），失败直接隐藏；
  // 只展示 1 条精选（优先取有描述的条目，信息更丰富；无描述则取年份最早一条），总数留给「共 N 条」提示
  loadTih() {
    api.fetchTodayInHistory((err, items) => {
      if (err || !items) {
        if (this.data.tih.length) this.setData({ tih: [], tihTotal: 0, tihMore: false, tihDate: '' });
        return;
      }
      const now = new Date();
      const featured = items.find((item) => item.desc) || items[0];
      this.setData({
        tih: [featured],
        tihTotal: items.length,
        tihMore: items.length > 1,
        tihDate: `${now.getMonth() + 1}月${now.getDate()}日`
      });
    });
  },

  goDiscover() {
    wx.switchTab({ url: '/pages/discover/discover' });
  },

  goPage(e) {
    const page = e.currentTarget.dataset.page;
    const history = hd.get();

    if (page === 'timeline') {
      wx.switchTab({ url: '/pages/timeline/timeline' });
      return;
    }

    if (page === 'dynasty') {
      this.openSheet(
        '选择一个时代',
        history.periods.map((item) => ({ id: item.id, kind: 'period', title: item.name, sub: `${item.start < 0 ? '公元前' + (-item.start) : item.start}–${item.end} · ${item.title}` }))
      );
      return;
    }

    if (page === 'person') {
      this.openSheet(
        '选择一位人物',
        history.persons.map((item) => ({ id: item.id, kind: 'person', title: item.name, sub: `${item.era} · ${item.roles}` }))
      );
      return;
    }

    if (page === 'event') {
      const items = history.events.slice(-6).reverse();
      this.openSheet(
        '选择一件史事',
        items.map((item) => ({ id: item.id, kind: 'event', title: item.title, sub: `${item.yearText} · ${item.era}` }))
      );
    }
  },

  openSheet(title, list) {
    this.setData({ sheet: { open: true, title, list } });
  },

  closeSheet() {
    this.setData({ 'sheet.open': false });
  },

  // 阻挡面板内点击冒泡到遮罩
  noop() {},

  onSheetItem(e) {
    const item = this.data.sheet.list[e.currentTarget.dataset.index];
    if (!item) return;
    const url =
      item.kind === 'person'
        ? `/pages/person/person?id=${item.id}`
        : item.kind === 'event'
          ? `/pages/event/event?id=${item.id}`
          : `/pages/period/period?id=${item.id}`;
    this.setData({ 'sheet.open': false });
    wx.navigateTo({ url });
  },

  showDetail(item) {
    const paragraphs = [
      item.dateText ? `时间：${item.dateText}` : '',
      item.desc || item.summary || '',
      item.source ? `史料：${item.source}` : ''
    ].filter(Boolean);

    this.setData({
      info: { open: true, title: item.title || item.name, paragraphs }
    });
  },

  onTihTap(e) {
    const item = this.data.tih[e.currentTarget.dataset.index];
    if (!item) return;
    this.setData({
      info: {
        open: true,
        title: `${item.yearText} · ${item.title}`,
        paragraphs: [item.desc || '上游百科暂无进一步说明。'],
        kind: 'tih'
      }
    });
  },

  closeInfo() {
    this.setData({ 'info.open': false });
  },

  onHeroTap() {
    const hero = this.data.hero;
    if (hero.eventId) {
      wx.navigateTo({ url: `/pages/event/event?id=${hero.eventId}` });
      return;
    }
    this.showDetail(hero);
  },

  onEraTap() {
    store.setPendingTimelineMode('ancient');
    wx.switchTab({ url: '/pages/timeline/timeline' });
  },

  onModernTap() {
    store.setPendingTimelineMode('modern');
    wx.switchTab({ url: '/pages/timeline/timeline' });
  },

  onShareAppMessage() {
    return { title: '史页 · 一页一页读历史', path: '/pages/home/home' };
  }
});

