__register('/pages/archive-detail/archive-detail.js', function (require, module, exports) {
const font = require('../../utils/font.js');
const apk = require('../../utils/apkData.js');
const archiveImages = require('../../utils/archiveImages.js');
const archiveArt = require('../../utils/archiveArt.js');
const altArt = require('../../utils/eraImages.js').altArt;
const store = require('../../utils/store.js');
const entries = require('../../utils/entries.js');

function safeTitle(value, fallback) {
  if (!value) return fallback;
  try {
    return decodeURIComponent(value) || fallback;
  } catch (e) {
    return value;
  }
}

function blocksOf(text) {
  const source = String(text || '').replace(/\r\n/g, '\n');
  const blocks = [];
  source.split('\n').forEach((line) => {
    const value = line.trim();
    if (!value) return;
    const heading = /^#{1,6}\s+(.+)$/.exec(value);
    blocks.push({
      id: `b${blocks.length}`,
      kind: heading ? 'heading' : 'para',
      text: heading ? heading[1].trim() : value
    });
  });
  if (!blocks.length && source.trim()) {
    blocks.push({ id: 'b0', kind: 'para', text: source.trim() });
  }
  return blocks;
}

function toneOf(label) {
  if (label === '原文' || label === '诗文') return 'verse';
  if (label === '注释' || label === '译文') return 'note';
  return '';
}

// 把「【原文】/### 题解」这类内嵌小标题整理成独立段落，避免整页挤成一块。
function sectionsOf(text) {
  const source = String(text || '').replace(/\r\n/g, '\n');
  const sections = [];
  let current = null;

  const ensure = (label) => {
    current = {
      id: `s${sections.length}`,
      label: label || '',
      tone: toneOf(label || ''),
      paras: []
    };
    sections.push(current);
    return current;
  };

  const addPara = (value) => {
    const body = String(value || '').trim();
    if (!body) return;
    if (!current) ensure('');
    current.paras.push({
      id: `${current.id}-p${current.paras.length}`,
      text: body
    });
  };

  source.split('\n').forEach((line) => {
    const value = line.trim();
    if (!value) return;
    const heading = /^#{1,6}\s*(.+)$/.exec(value);
    if (heading) {
      ensure(heading[1].trim());
      return;
    }
    const bracket = /^【([^】]{1,12})】\s*(.*)$/.exec(value);
    if (bracket) {
      ensure(bracket[1].trim());
      if (bracket[2].trim()) addPara(bracket[2]);
      return;
    }
    addPara(value);
  });

  return sections.filter((section) => section.label || section.paras.length);
}

function factRowsOf(facts) {
  return (facts || [])
    .map((fact, index) => {
      const value = String(fact || '').trim();
      const match = /^([^：:]{1,10})[：:]\s*(.+)$/.exec(value);
      if (match) {
        return {
          id: `f${index}`,
          key: match[1].trim(),
          value: match[2].trim(),
          wide: false
        };
      }
      return { id: `f${index}`, key: '', value, wide: true };
    })
    .filter((row) => row.key || row.value);
}

Page('project://pages/archive-detail/archive-detail.js', {
  data: {
    kicker: '资料库',
    cover: '/assets/palace.jpg',
    art: '',
    item: null,
    blocks: [],
    sections: [],
    factRows: [],
    showLead: false,
    showMeta: false,
    showBody: false,
    showSections: false,
    showTranslation: false,
    loading: true,
    error: '',
    collected: false,
    fontClass: 'm'
  },

  onLoad(options) {
    font.apply(this);
    const opts = options || {};
    this.kind = opts.kind || 'figures';
    this.type = opts.type || '';
    this.id = safeTitle(opts.id, '');
    // 列表页会带上 shard；旧分享链接没有 shard 时，find 会先用索引定位。
    this.shard = opts.shard || (this.kind.indexOf('poems-') === 0 ? this.type : '');
    this.setData({
      kicker: safeTitle(opts.title, this.fallbackTitle(this.kind, this.type)),
      cover: archiveImages.cover(this.kind, this.type),
      loading: true,
      error: ''
    });
    this.fetch();
  },

  onShow() {
    font.apply(this);
    // 从收藏/足迹页返回时同步收藏态
    if (this.data.item) {
      this.setData({ collected: store.isFavorite('archive', this.entryKey()) });
    }
  },

  fallbackTitle(kind, type) {
    const meta = apk.getMeta();
    if (kind === 'cards') {
      const cat = (meta.categories || []).find((x) => x.key === type);
      return cat ? cat.name : '典籍辞条';
    }
    const section = (meta.sections || []).find((x) => x.key === kind);
    return section ? section.name : '资料库';
  },

  fetch() {
    this.setData({
      loading: true,
      error: '',
      item: null,
      art: '',
      blocks: [],
      sections: [],
      factRows: [],
      showLead: false,
      showMeta: false,
      showBody: false,
      showSections: false,
      showTranslation: false
    });
    apk.find(this.kind, this.type, this.id, this.shard, (err, item) => {
      if (err || !item) {
        this.setData({ loading: false, error: '资料加载失败，请检查网络后重试' });
        return;
      }
      this.shard = item.shard || this.shard;
      const kicker = this.data.kicker;
      const key = entries.archiveKey(this.kind, this.type, item.id);
      // 浏览足迹：带展示快照（标题/朝代身份/分类名/分卷），收藏与足迹页据此渲染，不回查远端数据
      store.addFootprint('archive', key, {
        info: {
          kind: this.kind,
          aType: this.type,
          shard: this.shard,
          rawId: item.id,
          cat: kicker,
          meta: item.meta || '',
          title: item.title
        }
      });
      const blocks = blocksOf(item.text);
      const sections = sectionsOf(item.text);
      const factRows = factRowsOf(item.facts);
      const hasTranslationSection = sections.some((section) => section.label === '译文');
      const showSections = sections.length > 0 && item.text !== item.title;
      this.setData({
        loading: false,
        error: '',
        item,
        collected: store.isFavorite('archive', key),
        art: archiveArt.entryImage(this.kind, item.id),
        blocks,
        sections,
        factRows,
        showSections,
        showBody: !showSections && blocks.length > 0 && item.text !== item.title,
        showTranslation: !!item.translation && !hasTranslationSection,
        showLead:
          this.kind !== 'cards' &&
          this.kind !== 'quotes' &&
          this.kind !== 'poemquotes' &&
          this.kind !== 'wenyan' &&
          this.kind.indexOf('poems-') !== 0 &&
          !!item.summary &&
          item.summary !== item.text,
        showMeta: !!item.meta && item.meta !== kicker
      });
    });
  },

  retry() {
    this.fetch();
  },

  // 收藏/足迹用的唯一键：kind|type|条目id（条目 id 各栏目内唯一）
  entryKey() {
    return entries.archiveKey(this.kind, this.type, this.data.item && this.data.item.id);
  },

  toggleCollect() {
    const key = this.entryKey();
    if (!key) return;
    const on = store.toggleFavorite('archive', key, {
      info: {
        kind: this.kind,
        aType: this.type,
        shard: this.shard,
        rawId: this.data.item.id,
        cat: this.data.kicker,
        meta: this.data.item.meta || '',
        title: this.data.item.title
      }
    });
    this.setData({ collected: on });
    wx.showToast({ title: on ? '已收藏' : '已取消收藏', icon: 'none' });
  },

  // 条目画片（远端图）加载失败 → 换备用 jsDelivr 域名重试一次；再失败置空隐藏画片（露出纯文字版式）
  onArtErr() {
    this.setData({ art: altArt(this.data.art) });
  },

  goBack() {
    wx.navigateBack({ fail: () => wx.redirectTo({ url: '/pages/archive/archive' }) });
  },

  onShareAppMessage() {
    const item = this.data.item;
    return {
      title: item ? `史页 · ${item.title}` : '史页 · 资料库',
      path: `/pages/archive-detail/archive-detail?kind=${this.kind}&type=${encodeURIComponent(this.type)}&shard=${encodeURIComponent(this.shard || '')}&title=${encodeURIComponent(this.data.kicker)}&id=${encodeURIComponent(this.id)}`
    };
  }
});

});
__register('/pages/archive-detail/archive-detail.wxml', function (require, module, exports) { module.exports = "<view class=\"page fs-{{fontClass}}\">\r\n  <image class=\"paper-bg\" src=\"/assets/paper-bg.jpg\" mode=\"aspectFill\"></image>\r\n  <view class=\"screen\">\r\n    <view class=\"topbar\">\r\n      <view class=\"back\" bindtap=\"goBack\" hover-class=\"back-pressed\" hover-stay-time=\"80\">\r\n        <view class=\"back-icon\">\r\n          <view class=\"back-chevron\"></view>\r\n          <view class=\"back-shaft\"></view>\r\n        </view>\r\n        <view class=\"back-divider\"></view>\r\n        <text class=\"back-label\">返回</text>\r\n      </view>\r\n      <text class=\"top-title\">资料库</text>\r\n      <image class=\"top-seal\" src=\"/assets/seal.png\" mode=\"aspectFit\"></image>\r\n    </view>\r\n\r\n    <view wx:if=\"{{loading}}\" class=\"state-card\">\r\n      <text class=\"state-title\">正在打开资料</text>\r\n      <text class=\"state-desc\">首次加载需要片刻。</text>\r\n    </view>\r\n\r\n    <view wx:elif=\"{{error}}\" class=\"state-card error\" bindtap=\"retry\">\r\n      <text class=\"state-title\">{{error}}</text>\r\n      <text class=\"state-action\">点此重试</text>\r\n    </view>\r\n\r\n    <block wx:else>\r\n      <view class=\"head-card\">\r\n        <view class=\"head-cover-wrap\">\r\n          <image class=\"head-cover\" src=\"{{cover}}\" mode=\"aspectFill\"></image>\r\n          <view class=\"head-cover-fade\"></view>\r\n        </view>\r\n        <view class=\"head-body\">\r\n          <view class=\"head-row\">\r\n            <view class=\"head-copy\">\r\n              <text class=\"head-kicker\">{{kicker}}</text>\r\n              <text class=\"head-title\">{{item.title}}</text>\r\n            </view>\r\n            <view wx:if=\"{{art}}\" class=\"head-fig\">\r\n              <image class=\"head-fig-img\" src=\"{{art}}\" mode=\"aspectFit\" binderror=\"onArtErr\"></image>\r\n            </view>\r\n          </view>\r\n          <text wx:if=\"{{showMeta}}\" class=\"head-meta\">{{item.meta}}</text>\r\n        </view>\r\n      </view>\r\n\r\n      <view class=\"fav-row\">\r\n        <view class=\"fav-btn {{collected ? 'on' : ''}}\" bindtap=\"toggleCollect\" hover-class=\"fav-pressed\" hover-stay-time=\"80\">\r\n          <text>{{collected ? '✓ 已收藏' : '收藏此资料'}}</text>\r\n        </view>\r\n      </view>\r\n\r\n      <view wx:if=\"{{showLead || showSections || showBody || showTranslation}}\" class=\"body-card\">\r\n        <view wx:if=\"{{showLead}}\" class=\"lead\">\r\n          <text>{{item.summary}}</text>\r\n        </view>\r\n\r\n        <view wx:if=\"{{showSections}}\" class=\"sections\">\r\n          <view wx:for=\"{{sections}}\" wx:key=\"id\" class=\"section {{item.tone}}\">\r\n            <view wx:if=\"{{item.label}}\" class=\"section-head\">\r\n              <text class=\"section-label\">{{item.label}}</text>\r\n              <text class=\"section-rule\"></text>\r\n            </view>\r\n            <text\r\n              wx:for=\"{{item.paras}}\"\r\n              wx:key=\"id\"\r\n              class=\"section-para\"\r\n            >{{item.text}}</text>\r\n          </view>\r\n        </view>\r\n\r\n        <block wx:elif=\"{{showBody}}\">\r\n          <block wx:for=\"{{blocks}}\" wx:key=\"id\">\r\n            <text wx:if=\"{{item.kind === 'heading'}}\" class=\"para-head\">{{item.text}}</text>\r\n            <view wx:else class=\"para\">\r\n              <text>{{item.text}}</text>\r\n            </view>\r\n          </block>\r\n        </block>\r\n\r\n        <view wx:if=\"{{showTranslation}}\" class=\"translation\">\r\n          <text class=\"trans-title\">译文</text>\r\n          <text class=\"trans-text\">{{item.translation}}</text>\r\n        </view>\r\n      </view>\r\n\r\n      <view wx:if=\"{{factRows.length}}\" class=\"facts\">\r\n        <view class=\"facts-head\">\r\n          <text class=\"facts-title\">资料卡</text>\r\n          <text class=\"facts-count\">{{factRows.length}} 项</text>\r\n        </view>\r\n        <view class=\"fact-grid\">\r\n          <view wx:for=\"{{factRows}}\" wx:key=\"id\" class=\"fact-item {{item.wide ? 'wide' : ''}}\">\r\n            <text wx:if=\"{{item.key}}\" class=\"fact-key\">{{item.key}}</text>\r\n            <text class=\"fact-value\">{{item.value}}</text>\r\n          </view>\r\n        </view>\r\n      </view>\r\n\r\n      <view wx:if=\"{{item.source}}\" class=\"source-line\">来源：{{item.source}} · 史页资料库</view>\r\n    </block>\r\n  </view>\r\n</view>\r\n"; });
